const $=(s,r=document)=>r.querySelector(s);
const escapar=(v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const linkSeguro=u=>{if(typeof u!=='string'||!u.trim())return'';try{const p=new URL(u,location.origin);return['http:','https:'].includes(p.protocol)?p.href:''}catch{return''}};
const fontesIdiomas=[
 ['curt','Biblioteca Digital Curt Nimuendajú'],['museu','Museu Nacional dos Povos Indígenas'],['isa','Instituto Socioambiental · ISA'],['ailla','AILLA'],['olac','OLAC'],['bdtd','BDTD / IBICT'],['tatoeba','Tatoeba'],['panlex','PanLex'],['wiktionary','Wikcionário / Wiktionary'],['lingualibre','Lingua Libre'],['fsi','FSI Language Courses'],['dli','DLI GLOSS'],['merlot','MERLOT World Languages'],['libretexts','LibreTexts'],['elar','ELAR'],['dobes','DOBES / The Language Archive'],['kaipuleohone','Kaipuleohone'],['corsal','CoRSAL'],['coerll','COERLL'],['oercommons','OER Commons'],['livelingua','Peace Corps / Live Lingua']
].map(([id,nome])=>({id,nome}));
const estado={consulta:'',resultados:[],porFonte:{},buscando:false,token:0};
function abrirIdiomas(){const painel=$('#painel');if(painel?.open)painel.close();const d=$('#idiomas');if(!d.open)d.showModal();setTimeout(()=>$('#campo-idiomas')?.focus(),40);renderizar()}
function capaSimbolica(item){const simbolo=item.tipo?.includes('Áudio')?'◉':item.tipo?.includes('Dicionário')?'Aa':item.tipo?.includes('Curso')?'A':item.tipo?.includes('Gramática')?'G':'L';return`<div class="sem-capa" aria-hidden="true">${escapar(simbolo)}</div>`}
function normalizarResultados(lista){const vistos=new Set(),saida=[];for(const item of Array.isArray(lista)?lista:[]){const chave=(item.url||'')+'|'+(item.titulo||'');if(!item?.titulo||vistos.has(chave))continue;vistos.add(chave);saida.push(item)}return saida}
function renderizar(){const area=$('#resultados-idiomas');if(!area)return;const contagens={};for(const r of estado.resultados)if(r.modo!=='portal')contagens[r.fonte]=(contagens[r.fonte]||0)+1;const estados=fontesIdiomas.map(f=>({id:f.id,nome:f.nome,dados:estado.porFonte[f.id],quantidade:contagens[f.id]||0}));const conectadas=estados.filter(x=>x.dados&&!x.dados.portal&&!x.dados.erro).length,portais=estados.filter(x=>x.dados?.portal).length,erros=estados.filter(x=>x.dados?.erro).length;$('#status-idiomas').textContent=estado.consulta?`${estado.resultados.length} ${estado.resultados.length===1?'material encontrado':'materiais encontrados'} · ${fontesIdiomas.length} fontes especializadas consultadas${conectadas?` · ${conectadas} com resultados diretos`:''}${portais?` · ${portais} catálogos oficiais`:''}${erros?` · ${erros} falha${erros===1?'':'s'} temporária${erros===1?'':'s'}`:''}`:'Pesquise um idioma, povo, gramática, curso, palavra ou material de estudo.';const chips=$('#fontes-idiomas-status');chips.hidden=!estado.consulta&&!estado.buscando;chips.innerHTML=estados.map(x=>`<span class="fonte-chip ${x.dados?.erro?'erro':x.dados?'ok':'espera'}"><b>${escapar(x.nome)}</b><i>${x.dados?.erro?'×':x.dados?.portal?'↗':x.dados?x.quantidade:'…'}</i></span>`).join('');const carga=$('#carregando-idiomas');carga.hidden=!estado.buscando;carga.setAttribute('aria-hidden',String(!estado.buscando));if(estado.buscando){$('#carregando-idiomas-titulo').textContent='Percorrendo cursos, arquivos e acervos linguísticos…';$('#carregando-idiomas-fonte').textContent='Consultando somente as fontes especializadas de idiomas.';$('#progresso-idiomas-barra').style.width='62%';$('#progresso-idiomas-texto').textContent=`Consultando ${fontesIdiomas.length} fontes especializadas`}else if(estado.consulta){$('#progresso-idiomas-barra').style.width='100%';$('#progresso-idiomas-texto').textContent=`${fontesIdiomas.length} de ${fontesIdiomas.length} fontes consultadas`}area.setAttribute('aria-busy',String(estado.buscando));if(!estado.consulta&&!estado.buscando){area.innerHTML='<div class="estado-vazio"><h3>Uma biblioteca só para idiomas.</h3><p>Procure por Nheengatu, Guarani, Quechua, Mandarim, Latim, Japonês, Árabe, francês ou pelo nome de uma gramática, curso, povo ou palavra.</p></div>';return}if(estado.buscando&&!estado.resultados.length){area.innerHTML='<div class="estado-vazio"><h3>Abrindo cursos e arquivos…</h3><p>A busca de Idiomas não consulta as fontes gerais da Biblioteca.</p></div>';return}area.innerHTML=estado.resultados.length?estado.resultados.map(item=>{const url=linkSeguro(item.url),audio=linkSeguro(item.audio),portal=item.modo==='portal';return`<article class="resultado">${capaSimbolica(item)}<div><h3>${escapar(item.titulo)}</h3><p>${escapar(item.descricao||'Material para estudo de idiomas.')}</p><div class="meta-livro"><span>${escapar(item.tipo||'Material de idioma')}</span><span>${escapar(item.provedor||'Fonte especializada')}</span>${item.idioma?`<span>${escapar(item.idioma)}</span>`:''}<span class="tipo-acesso ${portal?'catalogo':'integral'}">${portal?'Busca no catálogo':'Resultado direto'}</span></div><div class="acoes-resultado">${url?`<a class="ler" href="${escapar(url)}" target="_blank" rel="noopener noreferrer">${portal?'Pesquisar na fonte':'Abrir material'} ↗</a>`:''}${audio?`<a href="${escapar(audio)}" target="_blank" rel="noopener noreferrer">Ouvir áudio ↗</a>`:''}</div></div></article>`}).join(''):`<div class="estado-vazio"><h3>Nenhum material apareceu nesta tentativa.</h3><p>Tente o nome do idioma em português e depois no nome original, ou pesquise por “gramática”, “curso”, “dicionário” ou “apostila” junto do idioma.</p></div>`}
async function pesquisar(q){q=String(q||'').trim();estado.consulta=q;estado.resultados=[];estado.porFonte={};const token=++estado.token;if(!q){estado.buscando=false;renderizar();return}estado.buscando=true;renderizar();try{const c=new AbortController(),timer=setTimeout(()=>c.abort(),12500);let r;try{r=await fetch(`/api/idiomas?q=${encodeURIComponent(q)}`,{signal:c.signal,headers:{Accept:'application/json'}})}finally{clearTimeout(timer)}if(!r.ok)throw Error();const d=await r.json();if(token!==estado.token)return;estado.resultados=normalizarResultados(d.resultados);estado.porFonte=d.porFonte||{}}catch{if(token!==estado.token)return;estado.resultados=[];estado.porFonte={};for(const f of fontesIdiomas)estado.porFonte[f.id]={nome:f.nome,quantidade:0,portal:false,erro:true}}if(token!==estado.token)return;estado.buscando=false;renderizar()}
function injetarMenu(){const conteudo=$('#conteudo-painel'),explorar=conteudo?.querySelector('[data-acao="explorar"]');if(!explorar||conteudo.querySelector('[data-idiomas="abrir"]'))return;const bloco=document.createElement('div');bloco.className='item-painel';bloco.innerHTML='<button data-idiomas="abrir"><strong>Idiomas</strong><small>Cursos, apostilas, línguas indígenas e idiomas do mundo ↗</small></button>';explorar.closest('.item-painel')?.after(bloco)}
$('#abrir-idiomas')?.addEventListener('click',abrirIdiomas);$('#form-idiomas')?.addEventListener('submit',e=>{e.preventDefault();pesquisar($('#campo-idiomas').value)});document.addEventListener('click',e=>{const b=e.target.closest('[data-idiomas="abrir"]');if(!b)return;e.preventDefault();abrirIdiomas()});const alvo=$('#conteudo-painel');if(alvo)new MutationObserver(injetarMenu).observe(alvo,{childList:true,subtree:true});
window.BibliotecaIdiomas={abrir:abrirIdiomas,pesquisar};
